import { Combobox as BaseCombobox } from "@base-ui/react/combobox";
import type { ComponentPropsWithoutRef, ElementType } from "react";
import { cn } from "../../lib/cn";
import { useEasyUIRoot } from "../../provider/easyui-provider";
import { useFieldContext } from "../field/field";
import "../../styles/combobox.css";

type StaticClass<T extends ElementType> = Omit<ComponentPropsWithoutRef<T>, "className"> & {
  className?: string;
};

/**
 * Search-as-you-type picker. Filtering, keyboard navigation, and screen-reader
 * announcements come from Base UI. Put it inside a <Field> for the label and error.
 *
 * @example
 * <Combobox items={teams} itemToStringLabel={(t) => t.label}>
 *   <Field label="Team">
 *     <ComboboxInput placeholder="Search teams" />
 *   </Field>
 *   <ComboboxContent>
 *     <ComboboxEmpty>No team matches that search.</ComboboxEmpty>
 *     <ComboboxList>
 *       {(team) => <ComboboxItem key={team.value} value={team}>{team.label}</ComboboxItem>}
 *     </ComboboxList>
 *   </ComboboxContent>
 * </Combobox>
 */
export const Combobox = BaseCombobox.Root;

export function ComboboxInput({ className, ...props }: StaticClass<typeof BaseCombobox.Input>) {
  const field = useFieldContext();
  return (
    <div className="eui-combobox__control">
      <BaseCombobox.Input
        id={field?.id}
        aria-invalid={field?.invalid || undefined}
        aria-describedby={
          [field?.descriptionId, field?.errorId].filter(Boolean).join(" ") || undefined
        }
        className={cn("eui-input", "eui-combobox__input", className)}
        {...props}
      />
      <BaseCombobox.Trigger className="eui-combobox__trigger" aria-label="Show options">
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
          <path d="M4 6l4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </BaseCombobox.Trigger>
    </div>
  );
}

export function ComboboxContent({ className, children, ...props }: StaticClass<typeof BaseCombobox.Popup>) {
  const root = useEasyUIRoot();
  return (
    <BaseCombobox.Portal container={root ?? undefined}>
      <BaseCombobox.Positioner className="eui-popover__positioner" sideOffset={6}>
        <BaseCombobox.Popup className={cn("eui-combobox__popup", className)} {...props}>
          {children}
        </BaseCombobox.Popup>
      </BaseCombobox.Positioner>
    </BaseCombobox.Portal>
  );
}

export function ComboboxList({ className, ...props }: StaticClass<typeof BaseCombobox.List>) {
  return <BaseCombobox.List className={cn("eui-combobox__list", className)} {...props} />;
}

export function ComboboxItem({ className, children, ...props }: StaticClass<typeof BaseCombobox.Item>) {
  return (
    <BaseCombobox.Item className={cn("eui-combobox__item", className)} {...props}>
      <span className="eui-combobox__item-label">{children}</span>
      <BaseCombobox.ItemIndicator className="eui-combobox__check">
        <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">
          <path d="M3.5 8.5 6.5 11.5 12.5 4.5" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </BaseCombobox.ItemIndicator>
    </BaseCombobox.Item>
  );
}

export function ComboboxEmpty({ className, ...props }: StaticClass<typeof BaseCombobox.Empty>) {
  return <BaseCombobox.Empty className={cn("eui-combobox__empty", className)} {...props} />;
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

import { createContext, useContext, useMemo, useState, type CSSProperties, type HTMLAttributes, type ReactNode } from "react";
import { cn } from "../lib/cn";
import { getAccentPalette, isHexColor } from "../lib/color";

export type EasyUIRadius = "none" | "sm" | "md" | "lg" | "full";
export type EasyUITheme = "light" | "dark";

export interface EasyUIProviderProps extends Omit<HTMLAttributes<HTMLDivElement>, "style"> {
  /**
   * Brand color, as hex. Accent text color and hover shade are derived from it,
   * and every component using the accent updates. Defaults to the neutral ink
   * from the theme.
   */
  accent?: string;
  /** Corner radius for components that use the base radius. */
  radius?: EasyUIRadius;
  /** CSS font-family for sans-serif UI text. Load the font yourself. */
  fontFamily?: string;
  /** Force light or dark for this subtree. Omit to inherit from the page. */
  theme?: EasyUITheme;
  /** Extra inline styles. Merged after the theme variables, so they win. */
  style?: CSSProperties;
  children?: ReactNode;
}

const RADIUS: Record<EasyUIRadius, string> = {
  none: "var(--eui-radius-none)",
  sm: "var(--eui-radius-sm)",
  md: "var(--eui-radius-md)",
  lg: "var(--eui-radius-lg)",
  full: "var(--eui-radius-full)",
};

const EasyUIRootContext = createContext<HTMLElement | null>(null);

/**
 * The element of the nearest EasyUIProvider, or null outside one.
 * Portaled components (Dialog, Select) mount here so they inherit the theme.
 * @internal
 */
export function useEasyUIRoot(): HTMLElement | null {
  return useContext(EasyUIRootContext);
}

/**
 * Scopes theme customization to a subtree. Wrap your app (or a section of it)
 * once; everything inside picks up the chosen accent, radius, and font.
 * Portaled overlays (dialogs, selects) are mounted inside the provider too,
 * so they keep the same theme.
 */
export function EasyUIProvider({
  accent,
  radius,
  fontFamily,
  theme,
  className,
  style,
  children,
  ...rest
}: EasyUIProviderProps) {
  const [root, setRoot] = useState<HTMLDivElement | null>(null);

  const vars = useMemo(() => {
    const v: Record<string, string> = {};
    if (accent !== undefined) {
      if (!isHexColor(accent)) {
        throw new Error(`EasyUIProvider: accent "${accent}" must be a hex color (#rgb or #rrggbb).`);
      }
      const palette = getAccentPalette(accent);
      v["--eui-color-accent"] = palette.accent;
      v["--eui-color-accent-fg"] = palette.accentForeground;
      v["--eui-color-accent-hover"] = palette.accentHover;
    }
    if (radius !== undefined) {
      v["--eui-radius-base"] = RADIUS[radius];
    }
    if (fontFamily !== undefined) {
      v["--eui-font-sans"] = fontFamily;
    }
    return v;
  }, [accent, radius, fontFamily]);

  return (
    <EasyUIRootContext.Provider value={root}>
      <div
        {...rest}
        ref={setRoot}
        className={cn("eui-root", className)}
        data-theme={theme}
        style={{ ...vars, ...style } as CSSProperties}
      >
        {children}
      </div>
    </EasyUIRootContext.Provider>
  );
}

/**
 * Color helpers for runtime theming.
 *
 * Accepts 3- or 6-digit hex colors (with or without "#"). Everything else
 * is rejected up front so theme values can't silently produce unreadable text.
 */

export type RGB = readonly [number, number, number];

const HEX = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i;

export function isHexColor(value: string): boolean {
  return HEX.test(value.trim());
}

export function parseHex(value: string): RGB {
  const trimmed = value.trim();
  if (!HEX.test(trimmed)) {
    throw new Error(`easyui: "${value}" is not a valid hex color (use #rgb or #rrggbb).`);
  }
  let hex = trimmed.replace(/^#/, "");
  if (hex.length === 3) {
    hex = hex
      .split("")
      .map((c) => c + c)
      .join("");
  }
  const n = parseInt(hex, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

export function toHex([r, g, b]: RGB): string {
  return "#" + [r, g, b].map((v) => Math.round(v).toString(16).padStart(2, "0")).join("");
}

/** WCAG 2.x relative luminance, 0 (black) to 1 (white). */
export function relativeLuminance(rgb: RGB): number {
  const [r, g, b] = rgb.map((v) => {
    const c = v / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r! + 0.7152 * g! + 0.0722 * b!;
}

/** WCAG contrast ratio between two hex colors, from 1 to 21. */
export function contrastRatio(a: string, b: string): number {
  const la = relativeLuminance(parseHex(a));
  const lb = relativeLuminance(parseHex(b));
  const [hi, lo] = la > lb ? [la, lb] : [lb, la];
  return (hi + 0.05) / (lo + 0.05);
}

const ON_ACCENT_CANDIDATES = ["#ffffff", "#0a0a0a"] as const;

/**
 * Picks the foreground (white or near-black) with the highest contrast
 * against the given background. Used for text on custom accent colors.
 */
export function readableForeground(background: string): string {
  let best: string = ON_ACCENT_CANDIDATES[0];
  let bestRatio = 0;
  for (const candidate of ON_ACCENT_CANDIDATES) {
    const ratio = contrastRatio(background, candidate);
    if (ratio > bestRatio) {
      best = candidate;
      bestRatio = ratio;
    }
  }
  return best;
}

export interface AccentPalette {
  /** Normalized #rrggbb accent. */
  accent: string;
  /** Hover shade of the accent, computed here so the text check covers it. */
  accentHover: string;
  /** Foreground for text and icons on the accent and its hover shade. */
  accentForeground: string;
  /**
   * Lowest contrast of accentForeground across the accent and its hover shade.
   * Meets WCAG AA (4.5:1) for normal text when this is at least 4.5.
   */
  contrast: number;
}

/** How far the hover shade moves from the accent toward its contrast target. */
const HOVER_MIX = 0.12;

function mixRgb(a: RGB, b: RGB, amount: number): RGB {
  return [0, 1, 2].map((i) => a[i]! * (1 - amount) + b[i]! * amount) as unknown as RGB;
}

/**
 * The hover shade moves away from the foreground, so text gets more contrast
 * on hover, not less. White text darkens the accent. Dark text lightens it.
 */
function hoverFor(accent: string, foreground: string): string {
  const target: RGB = foreground === "#ffffff" ? [0, 0, 0] : [255, 255, 255];
  return toHex(mixRgb(parseHex(accent), target, HOVER_MIX));
}

/**
 * Derives the accent pair from one user-chosen color. Picks the foreground
 * (white or near-black) that gives the best worst-case contrast across the
 * accent and its hover shade, so text stays readable in both states.
 */
export function getAccentPalette(input: string): AccentPalette {
  const accent = toHex(parseHex(input));
  let best: AccentPalette | null = null;
  for (const foreground of ON_ACCENT_CANDIDATES) {
    const accentHover = hoverFor(accent, foreground);
    const contrast = Math.min(
      contrastRatio(accent, foreground),
      contrastRatio(accentHover, foreground),
    );
    if (!best || contrast > best.contrast) {
      best = { accent, accentHover, accentForeground: foreground, contrast };
    }
  }
  return best!;
}

import { createContext, useContext, useId, type HTMLAttributes, type ReactNode } from "react";
import { cn } from "../../lib/cn";
import "../../styles/field.css";

interface FieldContextValue {
  id: string;
  descriptionId: string | undefined;
  errorId: string | undefined;
  invalid: boolean;
}

const FieldContext = createContext<FieldContextValue | null>(null);

/** @internal Used by Input to wire label, description, and error ids. */
export function useFieldContext(): FieldContextValue | null {
  return useContext(FieldContext);
}

export interface FieldProps extends HTMLAttributes<HTMLDivElement> {
  /** Visible label. Rendered as a real <label> bound to the control. */
  label?: ReactNode;
  /** Helper text shown under the control. Linked via aria-describedby. */
  description?: ReactNode;
  /** Error message. Shown in place of nothing; also marks the control invalid. */
  error?: ReactNode;
  /** Marks the control invalid even without an error message. */
  invalid?: boolean;
  /** Overrides the generated control id. */
  id?: string;
}

/**
 * Groups a label, control, description, and error so the accessibility wiring
 * (for/id, aria-describedby, aria-invalid) is correct by default.
 */
export function Field({
  label,
  description,
  error,
  invalid,
  id,
  className,
  children,
  ...rest
}: FieldProps) {
  const generated = useId();
  const baseId = id ?? `eui-field-${generated.replace(/:/g, "")}`;
  const hasError = error !== undefined && error !== null && error !== false && error !== "";
  const isInvalid = invalid ?? hasError;

  const value: FieldContextValue = {
    id: baseId,
    descriptionId: description ? `${baseId}-description` : undefined,
    errorId: hasError ? `${baseId}-error` : undefined,
    invalid: !!isInvalid,
  };

  return (
    <FieldContext.Provider value={value}>
      <div className={cn("eui-field", className)} {...rest}>
        {label ? (
          <label className="eui-field__label" htmlFor={baseId}>
            {label}
          </label>
        ) : null}
        {children}
        {description ? (
          <p id={value.descriptionId} className="eui-field__description">
            {description}
          </p>
        ) : null}
        {hasError ? (
          <p id={value.errorId} className="eui-field__error" role="alert">
            {error}
          </p>
        ) : null}
      </div>
    </FieldContext.Provider>
  );
}

/* Combobox. The input is the Input look with a chevron trigger on the right.
   The popup and items match Select, so the two pickers feel like one family. */

.eui-combobox__control {
  position: relative;
  display: block;
  width: 100%;
}

.eui-combobox__input {
  padding-right: 36px;
}

.eui-combobox__trigger {
  position: absolute;
  top: 50%;
  right: 4px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  margin-top: -14px;
  border: 0;
  border-radius: var(--eui-radius-sm);
  background: transparent;
  color: var(--eui-color-fg-muted);
  cursor: pointer;
}

.eui-combobox__trigger:hover {
  background-color: var(--eui-color-hover);
  color: var(--eui-color-fg);
}

.eui-combobox__trigger:focus-visible {
  outline: 2px solid var(--eui-color-ring);
  outline-offset: 2px;
}

.eui-combobox__popup {
  box-sizing: border-box;
  width: var(--anchor-width);
  max-height: min(320px, var(--available-height));
  overflow-y: auto;
  padding: 4px;
  border-radius: var(--eui-radius-base);
  background-color: var(--eui-color-bg);
  color: var(--eui-color-fg);
  box-shadow:
    0 0 0 var(--eui-border-width) var(--eui-color-border),
    0 12px 32px -8px rgb(0 0 0 / 0.18);
  transform-origin: var(--transform-origin);
  transition:
    opacity var(--eui-duration-fast) var(--eui-easing-out),
    transform var(--eui-duration-fast) var(--eui-easing-out);
}

.eui-combobox__popup[data-starting-style],
.eui-combobox__popup[data-ending-style] {
  opacity: 0;
  transform: scale(0.96);
}

.eui-combobox__list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.eui-combobox__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 36px;
  padding: 0 10px;
  border-radius: var(--eui-radius-sm);
  font-size: 14px;
  cursor: default;
  user-select: none;
}

.eui-combobox__item[data-highlighted] {
  background-color: var(--eui-color-hover);
}

.eui-combobox__item[data-disabled] {
  opacity: 0.5;
}

.eui-combobox__check {
  display: inline-flex;
  color: var(--eui-color-fg);
}

.eui-combobox__empty {
  padding: 12px 10px;
  font-size: 14px;
  color: var(--eui-color-fg-muted);
}

@media (prefers-reduced-motion: reduce) {
  .eui-combobox__popup {
    transition: none;
  }
}

/* Field: label, description, and error. Layout only; the control is styled in input.css. */

.eui-field {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.eui-field__label {
  font-size: 13px;
  font-weight: 500;
  line-height: 1.4;
  color: var(--eui-color-fg);
  cursor: default;
}

.eui-field__description {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--eui-color-fg-muted);
}

.eui-field__error {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--eui-color-danger);
}
